// The whole point of greying rather than hiding: this column is read out of the
// corner of the eye, and one that re-orders itself as the cursor moves cannot
// be. Every row of the fixture must advertise the same keys, in the same order.
func TestTheShortcutColumnDoesNotMoveWithTheCursor(t *testing.T) {
	m := scannedModel(t)

	var want []string
	for cursor := 0; cursor < len(entryFixtures()); cursor++ {
		m.table.SetCursor(cursor)

		var got []string
		for _, s := range m.GetShortcuts() {
			got = append(got, s.Key)
		}
		if cursor == 0 {
			want = got
			continue
		}
		if strings.Join(got, " ") != strings.Join(want, " ") {
			t.Errorf("row %d advertises\n%v\nwant the same keys as row 0\n%v", cursor, got, want)
		}
	}

	// And with no row at all — the empty listing is the same mode.
	var empty []string
	for _, s := range newTestModel(t).GetShortcuts() {
		empty = append(empty, s.Key)
	}
	if strings.Join(empty, " ") != strings.Join(want, " ") {
		t.Errorf("an empty listing advertises\n%v\nwant\n%v", empty, want)
	}
}

